#include "elit21/shopify/bulk/BulkUploadManager.h"
#include "elit21/security/Crypto.h"
#include <filesystem>
#include <fstream>
#include <sstream>
namespace elit21::shopify::bulk {BulkUploadManager::BulkUploadManager():platform::BusinessComponent("BulkUploadManager","Verified Shopify bulk upload file manager",platform::BusinessComponentSpec{"shopify","prepare_bulk_upload",{"path"},false,false,4U*1024U*1024U}){}Result<BulkUploadFile>BulkUploadManager::inspect(const std::string&path,std::size_t maximum)const{std::error_code e;auto bytes=std::filesystem::file_size(path,e);if(e)return Result<BulkUploadFile>::failure("Cannot inspect upload file: "+e.message());if(bytes==0||bytes>maximum)return Result<BulkUploadFile>::failure("Upload file size is invalid");std::ifstream in(path,std::ios::binary);std::ostringstream data;data<<in.rdbuf();if(!in&& !in.eof())return Result<BulkUploadFile>::failure("Cannot read upload file");auto ext=std::filesystem::path(path).extension().string();std::string mime=ext==".jsonl"?"text/jsonl":ext==".json"?"application/json":"application/octet-stream";return Result<BulkUploadFile>::success({path,std::filesystem::path(path).filename().string(),mime,crypto::sha256Hex(data.str()),static_cast<std::size_t>(bytes)});}platform::OperationResult BulkUploadManager::execute(const platform::OperationContext&context){return executeBusiness(context);}}
